###########################################################
# Pilot simulation preview figures
#
# This script visualises the default pilot dataset generated by
# code/00_generate_data.R. It is kept separate from data generation so
# the generator can be sourced as a clean helper by fitting and Monte
# Carlo scripts.
###########################################################

if (!exists("project_root")) {
    source(file.path(Sys.getenv("PROJECT_ROOT", unset = getwd()), "code/utils.R"))
}

suppressPackageStartupMessages({
    library(tidyverse)
    library(neurogam)
    library(patchwork)
})

source(file.path(project_root(), "code/00_generate_data.R"))

sim_path <- data_path("sim_data_pilot.rds")
if (!file.exists(sim_path)) {
    pilot <- make_dataset(seed = 42)
    saveRDS(pilot$sim_data, data_path("sim_data_pilot.rds"))
    saveRDS(pilot$ground_truth, data_path("ground_truth_pilot.rds"))
}

sim_data <- readRDS(sim_path)
ground_truth <- readRDS(data_path("ground_truth_pilot.rds"))
fig_dir <- file.path(project_root(), "figures")
dir.create(fig_dir, showWarnings = FALSE, recursive = TRUE)

key_times <- st_take_n_times(
    time_vec = sort(unique(sim_data$time)),
    N = 8
)

eeg_data_summary <- sim_data %>%
    summarise(voltage = mean(eeg),
              .by = c(condition, channel, time, xproj, yproj)) %>%
    filter(time %in% key_times)

sensors <- unique(sim_data[, c("channel", "xproj", "yproj")])

p_cond1 <- plot_eeg(
    eeg_data_summary %>% filter(condition == "cond1"),
    type        = "topo",
    sensors     = sensors,
    times       = key_times,
    grid_res    = 200,
    value_col   = "voltage",
    facet_nrow  = 1,
    fill_limits = "global_quantile"
) + ggtitle("cond1 (noise only)")

p_cond2 <- plot_eeg(
    eeg_data_summary %>% filter(condition == "cond2"),
    type        = "topo",
    sensors     = sensors,
    times       = key_times,
    grid_res    = 200,
    value_col   = "voltage",
    facet_nrow  = 1,
    fill_limits = "global_quantile"
) + ggtitle("cond2 (signal + noise)")

ggsave(
    filename = file.path(fig_dir, "sim_data_topo_both.png"),
    plot = p_cond1 / p_cond2,
    width = 18, height = 6,
    dpi = 300, bg = "white"
)

seed_coord <- sim_data %>%
    distinct(channel, xproj, yproj) %>%
    filter(channel == ground_truth$seed_electrode)

spatial_truth <- sim_data %>%
    distinct(channel, xproj, yproj) %>%
    mutate(
        d_to_seed = sqrt((xproj - seed_coord$xproj)^2 +
                         (yproj - seed_coord$yproj)^2),
        w = if_else(
            d_to_seed <= ground_truth$sigma_space,
            exp(-d_to_seed^2 / (2 * ground_truth$sigma_space^2)),
            0
        ),
        w_label = round(w, 2)
    )

p_spatial_truth <- ggplot(spatial_truth, aes(x = xproj, y = yproj)) +
    geom_point(aes(colour = w, size = w)) +
    geom_text(aes(label = w_label), size = 4, vjust = -1, colour = "black") +
    scale_colour_gradient(low = "white", high = "red", name = "weight") +
    scale_size(range = c(1, 6), guide = "none") +
    labs(title = paste0("Spatial ground truth (sigma_space = ",
                        ground_truth$sigma_space, ")"),
         x = "x", y = "y") +
    coord_fixed() +
    theme_minimal()

ggsave(
    filename = file.path(fig_dir, "spatial_ground_truth.png"),
    plot = p_spatial_truth,
    width = 8, height = 7,
    dpi = 300, bg = "white"
)

cat("Saved pilot preview figures in: ", fig_dir, "\n", sep = "")
